def transform(grid):
    out=[row[:] for row in grid]
    objects=[]
    for color in {v for row in grid for v in row if v!=7}:
        cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        rs=[r for r,c in cells];cs=[c for r,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        single=len(cells)==1
        objects.append({'color':color,'single':single,'box':(r0,r1,c0,c1),'newbox':(r0-4,r0+4,c0-4,c0+4) if single else (r0,r1,c0,c1)})
    # Remove the borders of non-singleton rectangles.
    for o in objects:
        if not o['single']:
            r0,r1,c0,c1=o['box']
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if r in (r0,r1) or c in (c0,c1):out[r][c]=7
    # Expanded singletons fill only background cells.
    for o in objects:
        if o['single']:
            r0,r1,c0,c1=o['newbox'];color=o['color']
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    if 0<=r<len(grid) and 0<=c<len(grid[0]) and out[r][c]==7:out[r][c]=color
    # A shrunken rectangle moves one cell away from an adjacent rectangle.
    for o in objects:
        if o['single']:continue
        r0,r1,c0,c1=o['box'];dr=dc=0
        for q in objects:
            if q is o:continue
            a,b,d,e=q['newbox']
            if r1<a or b<r0:continue
            if e+1==c0:dc=1
            if d==c1+1:dc=-1
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                out[r][c]=7
                out[r+dr][c+dc]=o['color']
    return out
